%   returns cbar: real[1][49] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    gm = 0;
    re = 0;
    cbar = zeros(49, 1);
    gm = asils.models.gravfield.GRAV_DEFAULT_GM(1);
    re = asils.models.gravfield.GRAV_DEFAULT_RE(1);
    cbar = zeros(49, 1);
    cbar(1) = 1;
    for k = (0):((5) - 1)
        n = (k + 2);
        cbar(((n * 7)) + 1) = ((-(asils.models.gravfield.GRAV_DEFAULT_J((k) + 1))) / sqrt(((2 * n) + 1)));
    end
end
